-- Every fixture in this test is rolled back. No external payment or storage upload occurs.
begin;
do $$declare admin_id uuid;owner uuid;show_id bigint;episode bigint;object_path text;run uuid;test uuid;withdrawal uuid;baseline bigint;amount bigint;revision integer;result jsonb;counted bigint;begin
 select user_id into admin_id from public.cineo_admins limit 1;
 select s.owner_id,s.id,e.storage_path into owner,show_id,object_path from public.cineo_shows s join public.cineo_episodes e on e.show_id=s.id where s.status='approved' and not s.hidden and e.review_status='approved' and not e.hidden and not exists(select 1 from public.cineo_admins a where a.user_id=s.owner_id) and not exists(select 1 from public.cineo_creator_accounts c where c.user_id=s.owner_id) limit 1;
 if owner is null then raise exception 'A public fixture with an unenrolled non-admin owner is required';end if;
 if not exists(select 1 from public.cineo_follows where user_id=owner and kind='creator' and target=admin_id::text) then insert into public.cineo_follows(user_id,kind,target) values(owner,'creator',admin_id::text);if not exists(select 1 from public.cineo_follower_events where creator_id=admin_id and delta=1) then raise exception 'Follower history trigger failed';end if;end if;
 insert into public.cineo_creator_accounts(user_id,first_name,last_name,birth_date,status,approved_at) values(owner,'Fixture','Studio','1990-01-01','approved',now());
 insert into public.cineo_episodes(show_id,title,storage_path,season,episode_number,review_status,duration_seconds,media_state) values(show_id,'Rollback studio fixture','studio-fixture/'||gen_random_uuid()::text||'.mp4',999,9999,'approved',20,'ready') returning id into episode;
 insert into public.cineo_view_sessions(user_id,episode_id,last_at,source) values(admin_id,episode,now()-interval '20 seconds','search') returning id into run;
 result:=public.cineo_view_heartbeat(admin_id,run,10000,10000);
 if result->>'new_view'<>'true' then raise exception 'Qualified playback failed';end if;
 update public.cineo_view_sessions set last_at=now()-interval '10 seconds' where id=run;
 result:=public.cineo_view_heartbeat(admin_id,run,20000,20000);
 if not(select finished from public.cineo_view_sessions where id=run) then raise exception 'Completion was not recorded';end if;
 if not exists(select 1 from public.cineo_watch_spans where session_id=run) then raise exception 'Retention spans missing';end if;
 if not exists(select 1 from public.cineo_qualified_views where episode_id=episode and source='search') then raise exception 'Source attribution missing';end if;
 result:=public.cineo_episode_retention(owner,episode,7);if jsonb_array_length(result->'points')=0 then raise exception 'Retention report missing';end if;
 result:=public.cineo_studio_report(owner,7,show_id);if (result->>'finished_sessions')::integer<1 then raise exception 'Audience report missing completed session';end if;
 insert into public.cineo_ab_tests(creator_id,show_id,kind,baseline_title,baseline_cover,alternative,status) select owner,show_id,'title',title,coalesce(cover_path,''),'Fixture alternative','active' from public.cineo_shows where id=show_id returning id into test;
 perform public.cineo_record_exposure(admin_id,test,0,'started');perform public.cineo_record_exposure(admin_id,test,0,'seen');perform public.cineo_record_exposure(admin_id,test,0,'seen');
 select count(*) into counted from public.cineo_ab_exposures where test_id=test and user_id=admin_id and seen and started;if counted<>1 then raise exception 'Exposure deduplication or atomic flags failed';end if;
 result:=public.cineo_experiment_results(test);if (result->0->>'impressions')::integer<>1 or (result->0->>'starts')::integer<>1 then raise exception 'A/B report incorrect';end if;
 perform public.cineo_studio_delegate(admin_id,admin_id,owner,'finance');if public.cineo_studio_role(owner,admin_id)<>'finance' then raise exception 'Financial delegation failed';end if;
 perform public.cineo_studio_delegate(admin_id,admin_id,owner,'remove');if public.cineo_studio_role(owner,admin_id)<>'' or not exists(select 1 from public.cineo_creator_roles where creator_id=admin_id and user_id=owner and not active) then raise exception 'Grant revocation did not preserve inactive history';end if;
 insert into public.cineo_qualified_views(user_id,episode_id,show_id,creator_id,day,rate_cents_per_thousand) select null,episode,show_id,owner,'1901-01-31',40 from generate_series(1,24);
 insert into public.cineo_qualified_views(user_id,episode_id,show_id,creator_id,day,rate_cents_per_thousand) values(null,episode,show_id,owner,'1901-02-01',40);
 result:=public.cineo_studio_finance(owner);select (x->>'gross_cents')::bigint into amount from jsonb_array_elements(result->'months')x where x->>'month'='1901-02-01';if amount<>1 then raise exception 'Fractional cents were lost across months';end if;
 baseline:=(result->>'available_cents')::bigint;
 begin perform public.cineo_review_month(owner,owner,'1901-02-01',1,'Unauthorized review');raise exception 'UNAUTHORIZED_REVIEW';exception when others then if sqlerrm='UNAUTHORIZED_REVIEW' then raise;end if;end;
 begin perform public.cineo_review_month(admin_id,owner,'1901-02-01',2,'Excessive amount');raise exception 'EXCESSIVE_SETTLEMENT';exception when others then if sqlerrm='EXCESSIVE_SETTLEMENT' then raise;end if;end;
 result:=public.cineo_review_month(admin_id,owner,'1901-02-01',1,'Fixture reviewed amount');
 begin perform public.cineo_review_month(admin_id,owner,'1901-02-01',1,'Duplicate month');raise exception 'DUPLICATE_MONTH';exception when others then if sqlerrm='DUPLICATE_MONTH' then raise;end if;end;
 update public.cineo_payout_rules set enabled=true,minimum_cents=1,terms='Fixture payment rules',revision=public.cineo_payout_rules.revision+1 where id=1 returning public.cineo_payout_rules.revision into revision;
 amount:=baseline+1;
 result:=public.cineo_request_withdrawal(owner,amount,'{"iv":"fixture","ciphertext":"fixture"}','fixture',revision);withdrawal:=(result->>'id')::uuid;
 begin perform public.cineo_request_withdrawal(owner,1,'{"iv":"fixture","ciphertext":"fixture"}','fixture',revision);raise exception 'DOUBLE_RESERVATION';exception when others then if sqlerrm='DOUBLE_RESERVATION' then raise;end if;end;
 begin perform public.cineo_review_withdrawal(admin_id,withdrawal,'paid','Before approval','fixture');raise exception 'PAY_BEFORE_APPROVAL';exception when others then if sqlerrm='PAY_BEFORE_APPROVAL' then raise;end if;end;
 perform public.cineo_review_withdrawal(admin_id,withdrawal,'approved','Fixture approved','');
 begin perform public.cineo_review_withdrawal(admin_id,withdrawal,'paid','Missing reference','');raise exception 'MISSING_REFERENCE';exception when others then if sqlerrm='MISSING_REFERENCE' then raise;end if;end;
 perform public.cineo_review_withdrawal(admin_id,withdrawal,'paid','External payment fixture','fixture-'||gen_random_uuid()::text);
 begin perform public.cineo_review_withdrawal(admin_id,withdrawal,'paid','Duplicate payment','fixture-repeat');raise exception 'DUPLICATE_PAYMENT';exception when others then if sqlerrm='DUPLICATE_PAYMENT' then raise;end if;end;
 if (public.cineo_studio_finance(owner)->>'available_cents')::bigint<>0 then raise exception 'Balance reservation incorrect';end if;
 if not exists(select 1 from public.cineo_studio_audit where creator_id=owner and action='withdrawal_paid') then raise exception 'Payment audit missing';end if;
end$$;
select 'Playback spans, completion, sources, A/B exposure, team revocation, fractional cents, monthly review and payment state tests passed; all fixtures rolled back' as result;
rollback;
